"""Scratch-only tests; compile output is generated by a fake MetaEditor."""
import ctypes
import hashlib
import json
from pathlib import Path
import re
import subprocess
import tempfile
import unittest
from unittest.mock import Mock, patch

import source_build
import stage_recovery_install as prepare


def digest(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()


class StageInstallTests(unittest.TestCase):
    def setUp(self):
        scratch = tempfile.TemporaryDirectory()
        self.addCleanup(scratch.cleanup)
        self.root = Path(scratch.name)
        self.repo = self.root / "repo"
        self.repo.mkdir()
        self.parent = self.root / "new-stages"
        self.parent.mkdir()
        self.stage_parent = patch.object(prepare, "local_temp_parent", return_value=self.parent)
        self.stage_parent_mock = self.stage_parent.start()
        self.addCleanup(self.stage_parent.stop)
        self.git("init", "-q")
        self.git("config", "user.email", "test@example.invalid")
        self.git("config", "user.name", "Scratch test")
        for source in (*source_build.CANDIDATE, source_build.DIAGNOSTIC[-1]):
            target = self.repo / source_build.BASE / source
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_text("// fixture source only\n", encoding="utf-8")
        self.git("add", ".")
        self.git("commit", "-qm", "fixture")
        self.commit = self.git("rev-parse", "HEAD")
        self.archive = self.root / "source.zip"
        source_build.package(self.repo, self.commit, self.archive, source_build.TRADER)
        self.archive_hash = digest(self.archive)
        self.results = self.root / "native-results"
        editor = self.root / "MetaEditor64.exe"
        editor.write_bytes(b"not an installed executable")

        def mock_editor(command, **_kwargs):
            path = Path(re.search(r'/compile:"([^"]+)"', command).group(1))
            path.with_suffix(".ex5").write_bytes(path.name.encode("ascii"))
            path.with_suffix(".log").write_text("Private C:\\Users\\Fixture\\Desktop\nResult: 0 errors, 1 warning",
                                                encoding="utf-16")
            return subprocess.CompletedProcess(command, 0)

        with patch.object(source_build.sys, "platform", "win32"), \
             patch.object(source_build, "file_product_version", return_value=("5.0.0.6308", "5.0.0.6308")), \
             patch.object(source_build.subprocess, "run", side_effect=mock_editor):
            self.report = source_build.compile_sources(self.archive, self.commit, self.archive_hash,
                                                       editor, self.results, "candidate")

    def git(self, *args):
        result = subprocess.check_output(["git", "-C", str(self.repo), *args])
        return result.decode().strip()

    def stage(self):
        return prepare.prepare_stage(self.archive, self.commit, self.archive_hash, self.results)

    def test_exact_three_and_repeat_creates_fresh_directory(self):
        a, hash_a = self.stage()
        b, hash_b = self.stage()
        self.assertNotEqual(a, b)
        self.assertEqual(a.parent, self.parent)
        self.assertEqual(b.parent, self.parent)
        self.assertEqual(hash_a, hash_b)
        self.assertEqual(a.name[:18], "recovery-ea-stage-")
        self.assertEqual({f.name for f in a.iterdir()},
                         {"RecoveryTrader.ex5", "RecoveryVerifier.ex5", "RecoveryPriceWatcher.ex5",
                          prepare.STAGE_MANIFEST})
        file = a / prepare.STAGE_MANIFEST
        self.assertEqual(digest(file), hash_a)
        self.assertNotIn("Users", file.read_text())
        manifest = json.loads(file.read_text())
        self.assertEqual(manifest["status"], prepare.STAGE_STATUS)
        self.assertEqual(manifest["compiler"], self.report["compiler"])
        self.assertEqual(manifest["commit"], self.commit)
        self.assertEqual(manifest["source_archive_sha256"], self.archive_hash)
        for staged, original in zip(manifest["roles"], self.report["targets"], strict=True):
            self.assertEqual(staged["role"], original["role"])
            self.assertEqual(staged["source_sha256"], original["source_sha256"])
            self.assertEqual(staged["compile_log_sha256"], original["log_sha256"])
            self.assertEqual(digest(a/staged["file"]), original["ex5_sha256"])
            self.assertEqual(digest(b/staged["file"]), original["ex5_sha256"])
        self.assertEqual(len(list(self.results.iterdir())), 7)  # original native results untouched

    def test_missing_role_bad_archive_and_extra_file_write_nothing(self):
        ex5 = self.results/self.report["targets"][-1]["ex5"]
        content = ex5.read_bytes()
        ex5.unlink()
        with self.assertRaisesRegex(ValueError, "mismatched ex5"):
            self.stage()
        self.stage_parent_mock.assert_not_called()
        ex5.write_bytes(content)
        extra = self.results/"injected.ex5"
        extra.write_bytes(content)
        with self.assertRaisesRegex(ValueError, "Unexpected files"):
            self.stage()
        self.stage_parent_mock.assert_not_called()
        extra.unlink()
        with self.assertRaisesRegex(ValueError, "ZIP SHA"):
            prepare.prepare_stage(self.archive, self.commit, "f"*64, self.results)
        self.stage_parent_mock.assert_not_called()
        self.assertEqual(list(self.parent.iterdir()), [])

    def test_diagnostic_is_not_a_candidate(self):
        archive = self.root / "diagnostic.zip"
        source_build.package(self.repo, self.commit, archive)
        with self.assertRaisesRegex(ValueError, "candidate source archive"):
            prepare.prepare_stage(archive, self.commit, digest(archive), self.results)
        self.stage_parent_mock.assert_not_called()

    def test_changed_binary_between_check_and_copy_cleans_only_new_stage(self):
        old, old_hash = self.stage()
        base_copy = prepare.copy_verified_artifact

        def race(src, dst, hash_expected):
            if dst.name == "RecoveryTrader.ex5":
                src.write_bytes(b"unexpected replacement")
            return base_copy(src, dst, hash_expected)

        with patch.object(prepare, "copy_verified_artifact", side_effect=race):
            with self.assertRaisesRegex(ValueError, "changed after build verification"):
                self.stage()
        self.assertEqual(list(self.parent.iterdir()), [old])
        self.assertEqual(digest(old/prepare.STAGE_MANIFEST), old_hash)

    def test_windows_uses_local_fixed_volume(self):
        self.stage_parent.stop()
        api = Mock()
        api.GetDriveTypeW.return_value = 4  # DRIVE_REMOTE
        with patch.object(prepare.sys, "platform", "win32"), \
             patch.object(ctypes, "WinDLL", return_value=api, create=True), \
             patch.object(prepare.tempfile, "gettempdir", return_value=str(self.parent)):
            with self.assertRaisesRegex(ValueError, "local fixed-drive"):
                prepare.local_temp_parent()
            api.GetDriveTypeW.return_value = 3
            self.assertEqual(prepare.local_temp_parent(), self.parent.resolve())


if __name__ == "__main__":
    unittest.main()
